import math

def eps_at_order(z,q,steps,alpha,delta=1e-9):
 terms=[math.lgamma(alpha+1)-math.lgamma(i+1)-math.lgamma(alpha-i+1)+i*math.log(q)+(alpha-i)*math.log1p(-q)+(i*i-i)/(2*z*z) for i in range(alpha+1)]
 largest=max(terms)
 rdp=(largest+math.log(sum(math.exp(t-largest) for t in terms)))/(alpha-1)
 return steps*rdp-(math.log(delta)+math.log(alpha))/(alpha-1)+math.log1p(-1/alpha)
for label,z,q,steps,alpha in [('Repeated z=1.024 rows',1.024,0.0295,2006,4),('Headline high population',0.6144,0.00295,2034,3),('Headline lower population',2.048,0.0295,2006,9)]:
 print(label, ': epsilon at reported integer order =', round(eps_at_order(z,q,steps,alpha),4))
